CREATE TABLE IF NOT EXISTS governed_executions (id UUID PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id UUID NOT NULL REFERENCES workspaces(id),contract_id UUID NOT NULL,title TEXT NOT NULL,owner_user_id UUID NOT NULL,state TEXT NOT NULL CHECK(state IN('DRAFT','PLANNED','ACTIVE','SUSPENDED','COMPLETED','CANCELLED')),started_at TIMESTAMPTZ,completed_at TIMESTAMPTZ,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),version INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS execution_history (id UUID PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id UUID NOT NULL REFERENCES workspaces(id),execution_id UUID NOT NULL REFERENCES governed_executions(id),from_state TEXT,to_state TEXT NOT NULL,actor_id UUID NOT NULL,reason TEXT NOT NULL,sequence INTEGER NOT NULL,occurred_at TIMESTAMPTZ NOT NULL DEFAULT now(),UNIQUE(execution_id,sequence));
CREATE TABLE IF NOT EXISTS governed_milestones (id UUID PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id UUID NOT NULL REFERENCES workspaces(id),execution_id UUID NOT NULL REFERENCES governed_executions(id),parent_milestone_id UUID REFERENCES governed_milestones(id),title TEXT NOT NULL,owner_user_id UUID NOT NULL,state TEXT NOT NULL,duration_days INTEGER NOT NULL CHECK(duration_days>=0),created_at TIMESTAMPTZ NOT NULL DEFAULT now(),updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),version INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS milestone_dependencies (id UUID PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id UUID NOT NULL REFERENCES workspaces(id),execution_id UUID NOT NULL REFERENCES governed_executions(id),predecessor_id UUID NOT NULL REFERENCES governed_milestones(id),successor_id UUID NOT NULL REFERENCES governed_milestones(id),dependency_type TEXT NOT NULL DEFAULT 'FINISH_TO_START',created_at TIMESTAMPTZ NOT NULL DEFAULT now(),CHECK(predecessor_id<>successor_id),UNIQUE(predecessor_id,successor_id));
CREATE TABLE IF NOT EXISTS dod_versions (id UUID PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id UUID NOT NULL REFERENCES workspaces(id),milestone_id UUID NOT NULL REFERENCES governed_milestones(id),version INTEGER NOT NULL,status TEXT NOT NULL,criteria JSONB NOT NULL,created_by UUID NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),published_at TIMESTAMPTZ,content_hash TEXT NOT NULL,UNIQUE(milestone_id,version));
CREATE TABLE IF NOT EXISTS dod_evaluations (id UUID PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id UUID NOT NULL REFERENCES workspaces(id),milestone_id UUID NOT NULL REFERENCES governed_milestones(id),definition_id UUID NOT NULL REFERENCES dod_versions(id),results JSONB NOT NULL,mandatory_passed BOOLEAN NOT NULL,manual_review_required BOOLEAN NOT NULL,evidence_references JSONB NOT NULL,evaluated_by UUID NOT NULL,evaluated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS certification_requests (id UUID PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id UUID NOT NULL REFERENCES workspaces(id),execution_id UUID NOT NULL REFERENCES governed_executions(id),milestone_id UUID NOT NULL REFERENCES governed_milestones(id),dod_evaluation_id UUID NOT NULL REFERENCES dod_evaluations(id),requested_by UUID NOT NULL,status TEXT NOT NULL,reviewer_ids JSONB NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),version INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS certification_decisions (id UUID PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id UUID NOT NULL REFERENCES workspaces(id),certification_request_id UUID NOT NULL REFERENCES certification_requests(id),reviewer_id UUID NOT NULL,decision TEXT NOT NULL CHECK(decision IN('APPROVE','REJECT')),rationale TEXT NOT NULL,evidence_references JSONB NOT NULL,decided_at TIMESTAMPTZ NOT NULL DEFAULT now(),UNIQUE(certification_request_id,reviewer_id));
CREATE TABLE IF NOT EXISTS digital_certification_records (id UUID PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id UUID NOT NULL REFERENCES workspaces(id),certification_request_id UUID NOT NULL UNIQUE REFERENCES certification_requests(id),milestone_id UUID NOT NULL REFERENCES governed_milestones(id),certificate_number TEXT NOT NULL UNIQUE,canonical_hash TEXT NOT NULL,status TEXT NOT NULL,issued_by UUID NOT NULL,issued_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS payment_trigger_definitions (id UUID PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id UUID NOT NULL REFERENCES workspaces(id),milestone_id UUID NOT NULL REFERENCES governed_milestones(id),name TEXT NOT NULL,required_dod_definition_id UUID NOT NULL REFERENCES dod_versions(id),certification_required BOOLEAN NOT NULL,amount_minor BIGINT NOT NULL CHECK(amount_minor>0),currency TEXT NOT NULL,escrow_provider_key TEXT,status TEXT NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),version INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS payment_authorization_proposals (id UUID PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id UUID NOT NULL REFERENCES workspaces(id),trigger_id UUID NOT NULL REFERENCES payment_trigger_definitions(id),milestone_id UUID NOT NULL REFERENCES governed_milestones(id),certification_id UUID REFERENCES digital_certification_records(id),amount_minor BIGINT NOT NULL CHECK(amount_minor>0),currency TEXT NOT NULL,status TEXT NOT NULL,blockers JSONB NOT NULL,proposed_by UUID NOT NULL,proposed_at TIMESTAMPTZ NOT NULL DEFAULT now(),idempotency_key TEXT NOT NULL,UNIQUE(workspace_id,idempotency_key));
CREATE INDEX IF NOT EXISTS governed_executions_workspace_state_idx ON governed_executions(workspace_id,state);CREATE INDEX IF NOT EXISTS governed_milestones_execution_state_idx ON governed_milestones(execution_id,state);CREATE INDEX IF NOT EXISTS certification_requests_status_idx ON certification_requests(workspace_id,status);CREATE INDEX IF NOT EXISTS payment_proposals_status_idx ON payment_authorization_proposals(workspace_id,status);
ALTER TABLE governed_executions ENABLE ROW LEVEL SECURITY;ALTER TABLE governed_milestones ENABLE ROW LEVEL SECURITY;ALTER TABLE dod_versions ENABLE ROW LEVEL SECURITY;ALTER TABLE certification_requests ENABLE ROW LEVEL SECURITY;ALTER TABLE payment_trigger_definitions ENABLE ROW LEVEL SECURITY;ALTER TABLE payment_authorization_proposals ENABLE ROW LEVEL SECURITY;
DO $$ BEGIN CREATE POLICY governed_executions_workspace ON governed_executions USING(workspace_id=current_workspace_id() AND has_active_workspace_membership(workspace_id));EXCEPTION WHEN duplicate_object THEN NULL;END $$;DO $$ BEGIN CREATE POLICY governed_milestones_workspace ON governed_milestones USING(workspace_id=current_workspace_id() AND has_active_workspace_membership(workspace_id));EXCEPTION WHEN duplicate_object THEN NULL;END $$;DO $$ BEGIN CREATE POLICY dod_versions_workspace ON dod_versions USING(workspace_id=current_workspace_id() AND has_active_workspace_membership(workspace_id));EXCEPTION WHEN duplicate_object THEN NULL;END $$;DO $$ BEGIN CREATE POLICY certification_requests_workspace ON certification_requests USING(workspace_id=current_workspace_id() AND has_active_workspace_membership(workspace_id));EXCEPTION WHEN duplicate_object THEN NULL;END $$;DO $$ BEGIN CREATE POLICY payment_triggers_workspace ON payment_trigger_definitions USING(workspace_id=current_workspace_id() AND has_active_workspace_membership(workspace_id));EXCEPTION WHEN duplicate_object THEN NULL;END $$;DO $$ BEGIN CREATE POLICY payment_proposals_workspace ON payment_authorization_proposals USING(workspace_id=current_workspace_id() AND has_active_workspace_membership(workspace_id));EXCEPTION WHEN duplicate_object THEN NULL;END $$;
DO $$ BEGIN CREATE TRIGGER execution_history_append_only BEFORE UPDATE OR DELETE ON execution_history FOR EACH ROW EXECUTE FUNCTION prevent_append_only_mutation();EXCEPTION WHEN duplicate_object THEN NULL;END $$;DO $$ BEGIN CREATE TRIGGER certification_decisions_append_only BEFORE UPDATE OR DELETE ON certification_decisions FOR EACH ROW EXECUTE FUNCTION prevent_append_only_mutation();EXCEPTION WHEN duplicate_object THEN NULL;END $$;DO $$ BEGIN CREATE TRIGGER digital_certifications_append_only BEFORE UPDATE OR DELETE ON digital_certification_records FOR EACH ROW EXECUTE FUNCTION prevent_append_only_mutation();EXCEPTION WHEN duplicate_object THEN NULL;END $$;

ALTER TABLE execution_history ENABLE ROW LEVEL SECURITY;ALTER TABLE milestone_dependencies ENABLE ROW LEVEL SECURITY;ALTER TABLE dod_evaluations ENABLE ROW LEVEL SECURITY;ALTER TABLE certification_decisions ENABLE ROW LEVEL SECURITY;ALTER TABLE digital_certification_records ENABLE ROW LEVEL SECURITY;
DO $$ BEGIN CREATE POLICY execution_history_workspace ON execution_history USING(workspace_id=current_workspace_id() AND has_active_workspace_membership(workspace_id));EXCEPTION WHEN duplicate_object THEN NULL;END $$;DO $$ BEGIN CREATE POLICY milestone_dependencies_workspace ON milestone_dependencies USING(workspace_id=current_workspace_id() AND has_active_workspace_membership(workspace_id));EXCEPTION WHEN duplicate_object THEN NULL;END $$;DO $$ BEGIN CREATE POLICY dod_evaluations_workspace ON dod_evaluations USING(workspace_id=current_workspace_id() AND has_active_workspace_membership(workspace_id));EXCEPTION WHEN duplicate_object THEN NULL;END $$;DO $$ BEGIN CREATE POLICY certification_decisions_workspace ON certification_decisions USING(workspace_id=current_workspace_id() AND has_active_workspace_membership(workspace_id));EXCEPTION WHEN duplicate_object THEN NULL;END $$;DO $$ BEGIN CREATE POLICY digital_certification_records_workspace ON digital_certification_records USING(workspace_id=current_workspace_id() AND has_active_workspace_membership(workspace_id));EXCEPTION WHEN duplicate_object THEN NULL;END $$;
